// 读取上次保存的游标：nextSince 与 ETag（首次运行为空 → 拉全量快照）
const s = $getWorkflowStaticData('global');
return [{ json: { since: s.nextSince || '', etag: s.etag || '' } }];

// 保存新游标，并整理出有变动的城市
const r = $input.first().json;
const s = $getWorkflowStaticData('global');
const status = r.statusCode;
if (status === 304) return [{ json: { changed: [], status } }];
if (status === 400) { delete s.nextSince; delete s.etag; return [{ json: { changed: [], status, error: r.body } }]; } // BAD_SINCE → 重置游标
if (status !== 200) throw new Error(`房哨兵 HTTP ${status}: ${JSON.stringify(r.body)}`);
const body = r.body || {};
const headers = r.headers || {};
if (headers.etag) s.etag = headers.etag;
s.nextSince = body.nextSince || body.generatedAt || s.nextSince;
const cities = body.cities || [];
const changed = body.changedSince || cities.map(c => c.cityCode); // 首次无 since：全部视为变动
const lines = cities.map(c => `${c.city} ${c.dataDate}：${c.phase}（二手去化 ${c.secondHand?.inventoryCycle ?? '—'} 月）`);
return [{ json: { changed, status, message: lines.join('\n') } }];
